let angle = 0;
let radius = 0;
const MAX_RADIUS = Math.min(W, H) / 2 - 20;

function drawSpiral() {
    if (radius > MAX_RADIUS) return;

    // Calculate coordinates for spiral
    const x = W/2 + Math.cos(angle) * radius;
    const y = H/2 + Math.sin(angle) * radius;

    // Draw spiral segment
    if (radius === 0) {
        ctx.beginPath();
        ctx.moveTo(x, y);
    } else {
        ctx.lineTo(x, y);
    }

    ctx.stroke();

    // Increment angle and radius
    angle += 0.03;
    radius += 0.5;

    // Request next frame
    requestAnimationFrame(drawSpiral);
}

